sp_widget.client_script:
api.controller=function ($scope, spUtil, snRecordWatcher, $rootScope, $sce) {
	var c = this;
	$scope.standalone = $scope.options.standalone == 'true' || $scope.options.standalone == true;
  var q = "cmdb_ci.sys_class_name=cmdb_ci_service";
  if ($scope.data.outageIDs != "")
    q += "^NQsys_idIN" + $scope.data.outageIDs;

	spUtil.recordWatch($scope, "cmdb_ci_outage", q, function() {
		$scope.server.update();
		$rootScope.$broadcast("sp.outage.updated");
	});

	$scope.trustAsHtml = function(html) {
		return $sce.trustAsHtml(html);
	};

}

sp_widget.css:
/*
===============================================================================
CURRENT STATUS WIDGET — Modern Glassmorphism Theme
Paste into the CSS field of your cloned Current Status widget
===============================================================================
*/

/* Base Callout Card Container */
.bs-callout {
  margin: 16px 0 !important;
  padding: 16px 20px !important;
  border-radius: 12px !important;
  border: 1px solid #E2E8F0 !important;
  border-left-width: 6px !important; /* Sleeker, modern left accent strip */
  border-left-style: solid !important;
  background: rgba(255, 255, 255, 0.95) !important;
  backdrop-filter: blur(8px);
  color: #0F172A !important;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.04);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  position: relative;
  overflow: hidden;
}

.bs-callout:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.08);
}

/* Callout Variant — Service Outage (Danger / Red) */
.bs-callout-outage {
  background: linear-gradient(135deg, rgba(254, 242, 242, 0.9) 0%, rgba(255, 255, 255, 0.95) 100%) !important;
  border-color: rgba(239, 68, 68, 0.2) !important;
  border-left-color: $brand-danger !important;
}

.bs-callout-outage i,
.bs-callout-outage strong,
.bs-callout-outage a {
  color: #991B1B !important;
}

/* Callout Variant — Performance Degradation (Warning / Amber) */
.bs-callout-degradation {
  background: linear-gradient(135deg, rgba(254, 252, 232, 0.9) 0%, rgba(255, 255, 255, 0.95) 100%) !important;
  border-color: rgba(245, 158, 11, 0.2) !important;
  border-left-color: $brand-warning !important;
}

.bs-callout-degradation i,
.bs-callout-degradation strong,
.bs-callout-degradation a {
  color: #92400E !important;
}

/* Callout Variant — Planned Maintenance (Info / Blue) */
.bs-callout-planned {
  background: linear-gradient(135deg, rgba(240, 249, 255, 0.9) 0%, rgba(255, 255, 255, 0.95) 100%) !important;
  border-color: rgba(14, 165, 233, 0.2) !important;
  border-left-color: $brand-info !important;
}

.bs-callout-planned i,
.bs-callout-planned strong,
.bs-callout-planned a {
  color: #075985 !important;
}

/* Callout Variant — All Systems Operational (Success / Green) */
.bs-callout-success {
  background: linear-gradient(135deg, rgba(240, 253, 244, 0.9) 0%, rgba(255, 255, 255, 0.95) 100%) !important;
  border-color: rgba(34, 197, 94, 0.2) !important;
  border-left-color: $brand-success !important;
}

.bs-callout-success i,
.bs-callout-success strong,
.bs-callout-success a {
  color: #166534 !important;
}

/* Inner Details Spacing & Typography */
div.sp-outage-details {
  margin-bottom: 0 !important;
  font-size: 0.9rem !important;
  line-height: 1.5;
}

div.sp-outage-details h4, 
div.sp-outage-details .h4 {
  font-size: 1.05rem !important;
  font-weight: 800 !important;
  letter-spacing: -0.01em;
  margin-top: 0 !important;
  margin-bottom: 6px !important;
}

/* Tooltip Enhancements */
.tooltip-inner {
  max-width: 220px !important;
  width: auto !important;
  padding: 8px 12px !important;
  background-color: #0F172A !important;
  color: #FFFFFF !important;
  font-size: 0.75rem !important;
  font-weight: 600 !important;
  border-radius: 8px !important;
  box-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.25) !important;
}
/* Clean Panel Wrapper Styling */
.panel {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.panel-heading {
  background: transparent !important;
  border-bottom: 1px solid #E2E8F0 !important;
  padding: 12px 4px !important;
}

.panel-title {
  font-size: 1.1rem !important;
  font-weight: 800 !important;
  color: #0F172A !important;
}

.panel-body {
  padding: 12px 0 !important;
  color: #64748B !important;
}

/* Responsive adjustment */
@media (max-width: 768px) {
  .bs-callout {
    padding: 14px 16px !important;
  }
}

sp_widget.script:
// populate the 'data' object
// e.g., data.table = $sp.getValue('table');
var outage = new GlideRecordSecure("cmdb_ci_outage");
outage.addQuery("cmdb_ci.sys_class_name", "IN", options.sys_class_list || "cmdb_ci_service");
outage.addQuery("begin", "<=", gs.nowNoTZ());
outage.addQuery("end", ">=", gs.nowNoTZ()).addOrCondition("end", "=", "NULL");
data.service = (input && input.service) || $sp.getParameter("service");
if (!GlideStringUtil.nil(data.service)) {
  outage.addQuery("cmdb_ci", data.service);
	var serviceGR = new GlideRecordSecure("cmdb_ci_service");
	if (serviceGR.get(data.service))
		data.serviceDisplay = serviceGR.getDisplayValue();
}
outage.query();
data.outages = [];
data.outageIDs = "";
while (outage.next()) {
	var out = {};
	out.typeDisplay = outage.type.getDisplayValue();
	out.type = outage.getValue("type");
	out.details = outage.getValue("details");
	out.ci = outage.cmdb_ci.getDisplayValue();
	out.serviceID = outage.getValue("cmdb_ci");
	out.begin = outage.begin.getDisplayValue();
	data.outages.push(out);
	data.outageIDs += "," + outage.getUniqueValue();
}
